package cn.pulse.player;
import android.content.Context;
import java.io.*;
import java.util.*;
import org.json.*;
/** Portable library references. Audio files and Android URI grants are not copied. */
public final class LibraryBackup {
 public static final class Data {public final ArrayList<PlayerService.Track> queue,favorites;public final int mode;public final VisualSettings visuals;public JSONArray playlists=new JSONArray(),history=new JSONArray();Data(ArrayList<PlayerService.Track> q,ArrayList<PlayerService.Track> f,int m,VisualSettings v){queue=q;favorites=f;mode=m;visuals=v;}}
 public static String capture(Context context)throws Exception{String base=encode(new JSONArray(context.getSharedPreferences("MainActivity",0).getString("queue","[]")),new JSONArray(context.getSharedPreferences("favorites",0).getString("items","[]")),context.getSharedPreferences("playback",0).getInt("mode",0),VisualSettings.load(context));return new JSONObject(base).put("playlists",new JSONArray(context.getSharedPreferences("library",0).getString("playlists","[]"))).put("history",new JSONArray(context.getSharedPreferences("library",0).getString("history","[]"))).toString(2);}
 public static String encode(JSONArray queue,JSONArray favorites,int mode)throws Exception{return encode(queue,favorites,mode,null);}
 public static String encode(JSONArray queue,JSONArray favorites,int mode,VisualSettings visuals)throws Exception{
  JSONObject data=new JSONObject().put("format","gmusic.library.v1").put("createdAt",System.currentTimeMillis()).put("queue",queue).put("favorites",favorites).put("playbackMode",mode);
  if(visuals!=null)data.put("visuals",new JSONObject().put("circle",visuals.circle).put("motion",visuals.motion).put("bars",visuals.bars));return data.toString(2);
 }
 public static Data read(InputStream input)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=input.read(buf))!=-1){out.write(buf,0,n);if(out.size()>8*1024*1024)throw new IOException("备份文件超过 8 MB");}return parse(out.toString("UTF-8"));}
 public static Data parse(String text)throws Exception{JSONObject data=new JSONObject(text);if(!"gmusic.library.v1".equals(data.optString("format")))throw new IOException("不是 G music 收藏备份");ArrayList<PlayerService.Track> queue=tracks(data.getJSONArray("queue")),favorites=tracks(data.getJSONArray("favorites"));int mode=data.optInt("playbackMode",0);if(mode<0 || mode>2)throw new IOException("播放模式无效");VisualSettings visuals=null;if(data.has("visuals")){JSONObject v=data.getJSONObject("visuals");visuals=new VisualSettings(percent(v,"circle",VisualSettings.CIRCLE_MIN,VisualSettings.CIRCLE_MAX),percent(v,"motion",VisualSettings.MOTION_MIN,VisualSettings.MOTION_MAX),percent(v,"bars",VisualSettings.BARS_MIN,VisualSettings.BARS_MAX));}Data out=new Data(queue,favorites,mode,visuals);if(data.has("playlists")){out.playlists=data.getJSONArray("playlists");PlaylistStore.decode(out.playlists);}if(data.has("history")){out.history=data.getJSONArray("history");ListeningHistory.decode(out.history);}return out;}
 private static int percent(JSONObject data,String key,int min,int max)throws Exception{Object raw=data.get(key);if(!(raw instanceof Number))throw new IOException("视觉设置必须为整数百分比");double value=((Number)raw).doubleValue();if(Double.isNaN(value) || value<min || value>max || value!=(int)value)throw new IOException("视觉设置超出有效范围："+key);return (int)value;}
 static ArrayList<PlayerService.Track> tracks(JSONArray array)throws Exception{if(array.length()>10000)throw new IOException("备份的单个列表超过 10000 首");LinkedHashMap<String,PlayerService.Track> rows=new LinkedHashMap<>();for(int i=0;i<array.length();i++){JSONObject row=array.getJSONObject(i);String title=row.getString("title"),artist=row.getString("artist"),url=row.getString("url");int duration=row.optInt("duration",0);if(title.length()>2000 || artist.length()>1000 || url.length()>8192 || duration<0 || !validSource(url))throw new IOException("备份中存在无效歌曲，第 "+(i+1)+" 项");if(!rows.containsKey(url))rows.put(url,new PlayerService.Track(title,artist,url,duration));}return new ArrayList<>(rows.values());}
 static boolean validSource(String value){if(value.matches("bili:BV[0-9A-Za-z]{10}(?:\\?(?:cid|p)=\\d+)?"))return true;try{java.net.URI uri=new java.net.URI(value);if("content".equals(uri.getScheme()))return uri.getAuthority()!=null;if("https".equals(uri.getScheme()))return uri.getHost()!=null && uri.getRawUserInfo()==null;if(value.startsWith("bili-link:https://")){java.net.URI shortUri=new java.net.URI(value.substring(10));return "b23.tv".equalsIgnoreCase(shortUri.getHost()) && shortUri.getRawUserInfo()==null;}}catch(Exception ignored){}return false;}
 public static int mergeQueue(List<PlayerService.Track> current,List<PlayerService.Track> incoming){Set<String> known=new HashSet<>();for(PlayerService.Track t:current)known.add(t.url);int count=0;for(PlayerService.Track t:incoming)if(known.add(t.url)){current.add(t);count++;}return count;}
}
